import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as h,S}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"三层堆叠 SOC / SOG","description":"","frontmatter":{"title":"三层堆叠 SOC / SOG","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/trilayer-soc-sog.md","filePath":"litho/trilayer-soc-sog.md","lastUpdated":1789023840000}'),c={name:"litho/trilayer-soc-sog.md"};function p(_,a,O,C,m,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="三层堆叠-soc-sog" tabindex="-1">三层堆叠 SOC / SOG <a class="header-anchor" href="#三层堆叠-soc-sog" aria-label="Permalink to &quot;三层堆叠 SOC / SOG&quot;">​</a></h1><div class="epigraph"><p>薄成像胶要分辨率与随机性；厚底层要抗刻蚀。SOC / SOG 把两件事拆开，转印多一次开口。</p><footer>—— 对照先进节点 trilayer 公开流程：成像层 / SOG / SOC</footer></div><p><a href="/litho/ebr-edge-bead">上一课</a>切完珠。中心场若只涂一层厚 CAR，<a href="/litho/high-na-resist-budget">高 NA 薄胶</a> 与深宽比会打架。缺口是三层：薄光刻胶成像，SOG（spin-on glass）当硬掩模，SOC（spin-on carbon）当厚有机底层。后课软烤对每一层都做，本课只钉堆叠角色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单层厚胶：吸收、随机性、倒塌一起坏。单层薄胶：刻蚀预算不够。三层把「谁看见光子」和「谁扛等离子体」分开。缺口不是再写 <a href="/litho/standing-wave-barc">BARC</a> 的反射公式，而是谁开口、谁停。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自下而上：SOC 填形貌、给碳硬掩模厚度；SOG 给含硅层，对碳有选择比；成像胶薄，只把图形落到 SOG。显影后先开口 SOG，再开口 SOC，再进衬底。每一层旋涂+烘烤，均匀性误差会叠——旋涂课的 \\(d(r)\\) 现在有三张。</p>',7)),(e(),n(S,null,{default:r(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E8%96%84%E6%88%90%E5%83%8F%E8%83%B6%22%5D%20--%3E%20SOG%5B%22SOG%22%5D%0A%20%20SOG%20--%3E%20SOC%5B%22SOC%22%5D%0A%20%20SOC%20--%3E%20SUB%5B%22%E8%A1%AC%E5%BA%95%22%5D%0A%20%20PR%20--%3E%20ETCH%5B%22%E5%BC%80%E5%8F%A3%E9%93%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">有的流程用 CVD 硬掩模替换 SOG。名字变了，分工不变：成像层薄、转印层抗刻蚀。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>含硅层在氧化性等离子体里相对碳更耐或相反，取决于气体——选择比是刻蚀课，本课只要求存在一层「停得住」的中间膜。SOC 的填孔能力决定下层金属沟槽上还要不要再平坦化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 DSA 或金属氧化物胶替代三层。下一课软烤：溶剂走了，堆叠才变成可曝光固体。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层拆开成像厚度与刻蚀厚度。</li><li>误差按层叠加；开口链是后课 BARC/硬掩模刻蚀的前置。</li><li>出处：先进节点 trilayer 公开流程通识。</li></ul>',7))])}const b=i(c,[["render",p]]);export{A as __pageData,b as default};
